import zipfile, re, docx
# leftover markers check
z=zipfile.ZipFile('output/offer_letter_filled.docx')
left=set()
for n in z.namelist():
    if n.endswith('.xml'):
        plain=re.sub(r'<[^>]+>','',z.read(n).decode('utf-8','ignore'))
        for m in re.findall(r'\{\{[^}]*\}\}',plain): left.add(m)
print('leftover markers:', left or 'NONE')
d=docx.Document('output/offer_letter_filled.docx')
full=[]
for p in d.paragraphs: full.append(p.text)
for t in d.tables:
    for row in t.rows:
        for c in row.cells:
            for p in c.paragraphs: full.append(p.text)
txt='\n'.join(full)
print('RELOCATION_AMOUNT present (3,125)?', '3,125' in txt)
print('relocation block dropped (amount should be absent since Yes has spaces)')
print('CUSTOMER_NAME present?', 'Nóra Singh' in txt)
print('DETAIL_NOTE present?', 'Ω check' in txt)
" 2>&1
